1	import { NextRequest, NextResponse } from "next/server";
2	
3	/**
4	 * Shareable referral link: /r/<code>, printed on the Refer & Earn page
5	 * (app/dashboard/refer/page.tsx) as `${APP_URL}/r/${code}`.
6	 *
7	 * Drops the same `nxeon_ref` cookie that `ReferralCapture` sets client-side for
8	 * the `?ref=` query-param case, then 302-redirects to /register. No DB lookup
9	 * here on purpose: `register` (lib/actions.ts, ~line 203) already only honors a
10	 * cookie value that matches a real `User.referralCode` or `ReferralPartner.code`
11	 * — this route's only job is translating the short link into that cookie.
12	 */
13	
14	const REF_COOKIE = "nxeon_ref";
15	const REF_COOKIE_TTL_SECONDS = 60 * 60 * 24 * 30; // 30 days, matches ReferralCapture
16	
17	export async function GET(req: NextRequest, { params }: { params: Promise<{ code: string }> }) {
18	  const { code: rawCode } = await params;
19	
20	  // Redirect against the PUBLIC origin, not req.nextUrl.origin: behind the nginx
21	  // proxy the request origin resolves to http://localhost:3000 (see app/go/[slug]).
22	  const publicOrigin = process.env.APP_URL ?? req.nextUrl.origin;
23	  const res = NextResponse.redirect(new URL("/register", publicOrigin), 302);
24	
25	  const code = rawCode.trim().toUpperCase().slice(0, 32);
26	  if (/^[A-Z0-9_-]+$/.test(code)) {
27	    res.cookies.set(REF_COOKIE, code, {
28	      path: "/",
29	      maxAge: REF_COOKIE_TTL_SECONDS,
30	      sameSite: "lax",
31	    });
32	  }
33	  return res;
34	}
