120	
121	  const org = await db.organization.findUnique({ where: { id: orgId }, select: { name: true } });
122	  if (!org) return { error: "Organization not found." };
123	
124	  if (invitedEmail === user.email.toLowerCase()) {
125	    return { error: "You're already a member of this organization." };
126	  }
127	
128	  // Narrow lookup, and the ONLY one allowed here: does this address already have
129	  // a Membership *in this org*? It answers nothing the caller can't already see —
130	  // they administer this org, so the roster and its addresses are theirs to read
131	  // (app/dashboard/team/page.tsx) — and it returns null for a non-member whether
132	  // or not that address has an account, so it is not the enumeration oracle the
133	  // old `db.user.findUnique` was. Saves emailing an invitation that would be a
134	  // no-op on accept.
135	  const alreadyIn = await db.membership.findFirst({
136	    where: { orgId, user: { email: invitedEmail } },
137	    select: { id: true },
138	  });
139	  if (alreadyIn) {
140	    return { error: "That person is already a member of this organization." };
141	  }
142	
143	  // Throttle per inviter. This action sends Nxeon-branded mail to an arbitrary
144	  // address chosen by the caller, so without a cap it is a spam relay and a way
145	  // to bury someone in invitations. Same shape as the login / password-reset
146	  // throttles (lib/rate-limit.ts).
147	  const rl = checkRateLimit(`org-invite:${user.id}`, { max: 10, windowMs: 60 * 60 * 1000 });
148	  if (!rl.ok) {
149	    return {
150	      error: `Too many invitations sent recently. Try again in ${Math.ceil(rl.retryAfterSec / 60)} minute(s).`,
151	    };
152	  }
153	
154	  const token = await signInviteToken({
155	    orgId,
156	    email: invitedEmail,
157	    role: wantRole,
158	    invitedBy: user.id,
159	  });
160	  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
161	  const acceptUrl = `${base}/dashboard/team/accept?token=${encodeURIComponent(token)}`;
162	
163	  /* RECORD the invite. The token stays the only thing that AUTHORISES — this
164	     row authorises nothing. It exists so an outstanding invite can be listed
165	     and, more importantly, CANCELLED: a signed token is otherwise valid until
166	     it expires, with no way to take it back once sent to the wrong address.
167	     Only the email the inviter typed is stored; the address is still never
168	     resolved to a user id, which is the property the stateless design was
169	     protecting. */
170	  // Must equal the JWE's own expiry (INVITE_TTL_HOURS, 72h/3 days) — this row is
171	  // display-only bookkeeping, but "display" still means the "expires" date shown
172	  // on the Invites tab has to be the truth. It used to be hardcoded to 7 days,
173	  // a leftover from before invites were re-designed as short-lived stateless
174	  // tokens (2026-09-12): the accept link itself died at 72 hours while this row,
175	  // and the "seven days" copy in TeamView.tsx, both kept promising 4 more days
176	  // of validity that no longer existed.
177	  const inviteExpiresAt = new Date(Date.now() + INVITE_TTL_HOURS * 60 * 60 * 1000);
178	  await db.orgInvite.upsert({
179	    where: { orgId_email: { orgId, email: invitedEmail } },
180	    create: {
181	      orgId, email: invitedEmail, role: wantRole, invitedById: user.id,
182	      tokenHash: createHash("sha256").update(token).digest("hex"),
183	      expiresAt: inviteExpiresAt,
184	    },
185	    update: {
186	      role: wantRole, invitedById: user.id,
187	      tokenHash: createHash("sha256").update(token).digest("hex"),
188	      expiresAt: inviteExpiresAt,
189	      revokedAt: null, acceptedAt: null,
190	    },
191	  }).catch(() => { /* display-only bookkeeping — never block a real invite */ });
192	
193	  const { sendMail, emails } = await import("./mailer");
194	  const tpl = emails.teamInvite({
195	    inviterName: user.name,
196	    teamName: org.name,
197	    acceptUrl,
198	  });
199	  // `template` is passed so the send is categorised in the admin EmailLog viewer
200	  // (same shape as worker/billing.ts:182). No `userId`: we deliberately never
201	  // resolved the address to an account, so there is no id to attribute it to.
202	  const sent = await sendMail({
203	    to: invitedEmail,
204	    subject: tpl.subject,
205	    html: tpl.html,
206	    template: tpl.template,
207	  });
208	  if (!sent) {
209	    // Report the failure instead of claiming the invitation went out. `sendMail`
210	    // returns false (and logs to EmailLog) when SMTP is unconfigured or the send
211	    // throws; a cheerful "Invitation sent." over a dropped email is exactly the
212	    // confidently-wrong surface this codebase keeps getting bitten by.
213	    return { error: "We couldn't send that invitation email. Check mail settings and try again." };
214	  }
215	
216	  await db.auditLog.create({
217	    data: {
218	      userId: user.id,
219	      action: "org.invite_sent",
220	      detail: `${invitedEmail} → ${wantRole}`,
221	    },
222	  });
223	  return {
224	    ok: true,
225	    message: `Invitation emailed to ${invitedEmail}. They join the organization when they accept it — the link expires in ${INVITE_TTL_HOURS} hours.`,
226	  };
