229	/**
230	 * Accept an invitation. This is the ONLY path that creates a Membership for
231	 * someone other than an org's creator, and it runs as the invitee — clicking
232	 * Accept while signed in as the invited address *is* the consent.
233	 *
234	 * Must be triggered by a deliberate click, never on page load: a mutation that
235	 * fires when the emailed URL is merely opened (or prefetched) would join people
236	 * to organizations without their agreement all over again.
237	 *
238	 * Re-checks at redemption time, because the token carries no server-side state:
239	 * the org still exists, the inviter still administers it, the role is still
240	 * sane, and the token's address matches the signed-in account.
241	 */
242	export async function acceptInvite(
243	  token: string,
244	): Promise<{ error?: string; ok?: boolean; orgName?: string; alreadyMember?: boolean }> {
245	  const user = await requireUser();
246	
247	  const claims = await verifyInviteToken(String(token ?? ""));
248	  /* A cancelled invite must stop working. Checked HERE, against the record
249	     written when it was sent — without this, "revoke" would be a button that
250	     changed a row and nothing else, and the signed token would keep letting
251	     someone in for its full seven days. */
252	  if (claims) {
253	    const rec = await db.orgInvite.findUnique({
254	      where: { orgId_email: { orgId: claims.orgId, email: claims.email } },
255	      select: { revokedAt: true },
256	    }).catch(() => null);
257	    if (rec?.revokedAt) {
258	      return { error: "This invitation has been cancelled. Ask for a new one." };
259	    }
260	  }
261	  if (!claims) {
262	    return {
263	      error: "This invitation link is invalid or has expired. Ask the organization owner to send a new one.",
264	    };
265	  }
266	
267	  // Bound to one address, so a forwarded link can't be redeemed by the recipient.
268	  if (claims.email !== user.email.trim().toLowerCase()) {
269	    return {
270	      error: "This invitation was sent to a different email address. Sign in as that account to accept it.",
271	    };
272	  }
273	
274	  if (!isRole(claims.role) || claims.role === "OWNER") {
275	    return { error: "This invitation carries an invalid role and can't be accepted." };
276	  }
277	
278	  const org = await db.organization.findUnique({
279	    where: { id: claims.orgId },
280	    select: { id: true, name: true },
281	  });
282	  if (!org) return { error: "That organization no longer exists." };
283	
284	  // Revocation, given there is no invitation row to delete: an outstanding
285	  // invitation dies the moment its sender loses the right to have sent it.
286	  const inviter = await actorMembership(org.id, claims.invitedBy);
287	  if (!inviter || !canAdministerOrg(inviter.role)) {
288	    return {
289	      error: "Whoever invited you no longer administers this organization, so the invitation is no longer valid.",
290	    };
291	  }
292	
293	  const existing = await actorMembership(org.id, user.id);
294	  if (existing) {
295	    return { ok: true, orgName: org.name, alreadyMember: true };
296	  }
297	
298	  await db.membership.create({
299	    data: { orgId: org.id, userId: user.id, role: claims.role },
300	  });
301	  // Close out the OrgInvite bookkeeping row: `acceptedAt` was written by nothing
302	  // before this fix, so an accepted invite stayed `acceptedAt: null` forever —
303	  // indistinguishable from still-pending — and app/dashboard/team/page.tsx's
304	  // `acceptedAt: null` filter kept showing this person under "Pending
305	  // invitations" alongside their now-real membership. There is no invite row for
306	  // a token minted before this schema field or before the invitee's address
307	  // matched a stored OrgInvite (upsert failures are swallowed in inviteMember),
308	  // so this is best-effort and never blocks the membership from being created.
309	  await db.orgInvite
310	    .updateMany({
311	      where: { orgId: org.id, email: claims.email, acceptedAt: null },
312	      data: { acceptedAt: new Date() },
313	    })
314	    .catch(() => {});

