/// A real payment made to a partner OFF-WALLET (bank transfer / Wise / PayPal /
/// invoice — see PartnerControls' payout form). Distinct from PartnerCommission
/// (what was EARNED): this is what was actually PAID, and can be a PARTIAL amount
/// ("$340 today even though $412 is accrued" — the owner's own example). A
/// partner's outstanding balance is therefore computed as
/// `sum(PartnerCommission, status != VOID) - sum(PartnerPayout)`, never by trying
/// to mark a fractional set of individual commission rows PAID. A FULL settlement
/// (adminSettlePartnerCommission) still flips every currently-ACCRUED commission
/// row to PAID for the per-row ledger display, AND records one PartnerPayout for
/// the same amount, so the two ledgers (earned vs. paid) always reconcile for the
/// common case; a PARTIAL payout (adminRecordPartnerPayout) only ever writes here
/// — the per-row commission ledger keeps showing ACCRUED until a later full
/// settlement, which is honest bookkeeping (accounting AR vs. a payments ledger),
/// not a bug.
model PartnerPayout {
  id            String          @id @default(cuid())
  partnerId     String
  partner       ReferralPartner @relation(fields: [partnerId], references: [id], onDelete: Cascade)
  amountCents   Int
  note          String?
  createdById   String?
  createdAt     DateTime        @default(now())

  @@index([partnerId, createdAt])
}

