// CREATOR PARTNER PROGRAM — DB-backed discount resolution.
//
// Pure math lives in lib/partner-discount.ts (unit-tested without a database);
// this file is the thin DB layer that resolves a real customer's real attachment
// state and calls it, plus the atomic first-purchase claim used inside a charge
// transaction. Mirrors the coupon-order.ts (pure) / order.ts (DB) split.

import type { Prisma } from "@prisma/client";
import { db } from "./db";
import { partnerDiscountPercent, type PartnerDiscountTier } from "./partner-discount";

export type ResolvedPartnerDiscount = {
  tier: PartnerDiscountTier;
  percent: number;
  partner: { id: string; name: string; code: string } | null;
};

const NONE: ResolvedPartnerDiscount = { tier: "NONE", percent: 0, partner: null };

async function resolveAttachment(userId: string) {
  return db.partnerCustomer.findUnique({
    where: { customerId: userId },
    select: {
      firstPurchaseDiscountUsedAt: true,
      partner: { select: { id: true, name: true, code: true, status: true } },
    },
  });
}

/**
 * Resolve the discount tier for a NEW (non-renewal) order of a non-domain
 * service. `userId` is optional so every quote-function call site can pass it
 * straight through the same options object it already threads a customer id
 * through (or omit it — e.g. an anonymous wizard preview before login — and get
 * `NONE`, byte-identical to pre-partner-program behavior).
 */
export async function partnerDiscountForNewOrder(
  userId: string | null | undefined,
): Promise<ResolvedPartnerDiscount> {
  if (!userId) return NONE;
  const attachment = await resolveAttachment(userId);
  if (!attachment) return NONE;
  const { tier, percent } = partnerDiscountPercent({
    attached: true,
    partnerActive: attachment.partner.status === "ACTIVE",
    isDomain: false,
    firstPurchaseAvailable: attachment.firstPurchaseDiscountUsedAt == null,
  });
  if (tier === "NONE") return NONE;
  return { tier, percent, partner: attachment.partner };
}

/**
 * Resolve the discount tier for a RENEWAL. Always collapses to RECURRING (10%)
 * or NONE — a renewal is, by construction, never anyone's first purchase (see
 * lib/partner-discount.ts's own doc comment on `firstPurchaseAvailable`).
 */
export async function partnerDiscountForRenewal(
  userId: string | null | undefined,
): Promise<ResolvedPartnerDiscount> {
  if (!userId) return NONE;
  const attachment = await resolveAttachment(userId);
  if (!attachment) return NONE;
  const { tier, percent } = partnerDiscountPercent({
    attached: true,
    partnerActive: attachment.partner.status === "ACTIVE",
    isDomain: false,
    firstPurchaseAvailable: false,
  });
  if (tier === "NONE") return NONE;
  return { tier, percent, partner: attachment.partner };
}

/**
 * PRE-REGISTRATION preview only: does this raw `nxeon_ref` cookie value resolve
 * to a real, ACTIVE partner code? Used SOLELY to show an anonymous visitor "you'll
 * get 50% off your first order" messaging on public marketing/pricing pages —
 * never to price an actual charge. A visitor in this state has no PartnerCustomer
 * row yet (that is only created at registration — see lib/actions.ts register()),
 * so there is nothing to look up but the code itself.
 */
export async function partnerPreviewForCode(
  rawCode: string | null | undefined,
): Promise<{ active: boolean; partnerName: string | null }> {
  const code = (rawCode ?? "").trim().toUpperCase();
  if (!code) return { active: false, partnerName: null };
  const partner = await db.referralPartner.findUnique({
    where: { code },
    select: { status: true, name: true },
  });
  if (!partner || partner.status !== "ACTIVE") return { active: false, partnerName: null };
  return { active: true, partnerName: partner.name };
}

/**
 * Same preview, but for an ALREADY-SIGNED-IN customer viewing a marketing/pricing
 * page before their first purchase — reads the real attachment (if any) instead of
 * a cookie, so the banner is correct even if their `nxeon_ref` cookie has since
 * expired or been cleared (the attachment itself is what's permanent).
 */
export async function partnerPreviewForUser(
  userId: string | null | undefined,
): Promise<{ active: boolean; tier: PartnerDiscountTier; percent: number; partnerName: string | null }> {
  const resolved = await partnerDiscountForNewOrder(userId);
  return {
    active: resolved.tier !== "NONE",
    tier: resolved.tier,
    percent: resolved.percent,
    partnerName: resolved.partner?.name ?? null,
  };
}

/**
 * Atomically claim the first-purchase discount slot for a customer. Call ONLY
 * from inside the SAME database transaction that debits the wallet / records the
 * paid invoice for a charge that was quoted/sold at the FIRST-purchase (50%)
 * tier, and only when that tier applied. Returns true if this call is the one
 * that consumed the slot (the common case — always true for a customer's actual
 * first purchase); false if it was already consumed by a concurrent charge for
 * the SAME customer.
 *
 * On false, callers keep the price already quoted/charged rather than recompute
 * mid-transaction — see this module's own header comment for why that is an
 * accepted, narrow, low-severity race (a customer can only ever race against
 * their own other order, never another customer's), matching the swallow
 * discipline lib/order.ts already applies to a vanished promo/coupon hold.
 */
export async function claimPartnerFirstPurchase(
  tx: Prisma.TransactionClient,
  customerId: string,
): Promise<boolean> {
  const res = await tx.partnerCustomer.updateMany({
    where: { customerId, firstPurchaseDiscountUsedAt: null },
    data: { firstPurchaseDiscountUsedAt: new Date() },
  });
  return res.count === 1;
}

