export type PartnerSummary = {
  partnerId: string;
  name: string;
  code: string;
  commissionRatePct: number;
  status: string;
  customerCount: number;
  /** Lifetime commission ever EARNED (every non-VOID PartnerCommission row), in cents. */
  lifetimeCents: number;
  /** lifetimeCents minus every real PartnerPayout ever recorded — the real balance owed. */
  outstandingCents: number;
  /** Sum of every real PartnerPayout ever recorded (full settlements + partial payouts). */
  paidCents: number;
};

/**
 * Roll up a partner's standing: attached-customer count, lifetime commission
 * EARNED, and the real balance owed.
 *
 * `paidCents`/`outstandingCents` are computed from `PartnerPayout` — the ledger of
 * REAL payments made — not from summing PartnerCommission rows whose `status`
 * happens to read PAID. Two ledgers, "earned" (PartnerCommission) and "paid"
 * (PartnerPayout), net balance = earned − paid: the only way to honestly support
 * a PARTIAL payout ("$340 today even though $412 is accrued" — the owner's own
 * example) without inventing a way to mark a fractional set of commission rows
 * paid. A full settlement (adminSettlePartnerCommission) still flips every
 * ACCRUED row to PAID for the per-row ledger display, so for the common case the
 * two views agree; see PartnerPayout's own doc comment on the model.
 */
export async function computePartnerSummary(partnerId: string): Promise<PartnerSummary | null> {
  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
  if (!partner) return null;

  const [customerCount, lifetimeAgg, payoutAgg] = await Promise.all([
    db.partnerCustomer.count({ where: { partnerId } }),
    db.partnerCommission.aggregate({
      where: { partnerId, status: { not: "VOID" } },
      _sum: { amountCents: true },
    }),
    db.partnerPayout.aggregate({
      where: { partnerId },
      _sum: { amountCents: true },
    }),
  ]);

  const lifetimeCents = lifetimeAgg._sum.amountCents ?? 0;
  const paidCents = payoutAgg._sum.amountCents ?? 0;
  const outstandingCents = Math.max(0, lifetimeCents - paidCents);
  return {
    partnerId: partner.id,
    name: partner.name,
    code: partner.code,
    commissionRatePct: partner.commissionRatePct,
    status: partner.status,
    customerCount,
    lifetimeCents,
    outstandingCents,
    paidCents,
  };
}

export type PartnerFunnel = {
  /** Rows in ReferralClick for this partner's code — real link clicks recorded by
   *  app/partner/[code]/route.ts (and app/r/[code]/route.ts for the legacy path). */
  clicked: number;
  /** PartnerCustomer rows — real, permanently-attached signups. */
  signedUp: number;
  /** Distinct customers with at least one PartnerCommission row — their first paid purchase. */
  converted: number;
};

/**
 * Real click → signup → conversion funnel for one partner, shown on both the
 * partner's own dashboard and the admin detail page. Every number here is a real
 * count off a real table — no estimates, no placeholders (see this codebase's own
 * "never fabricate" rule).
 */
export async function partnerFunnel(partnerId: string, code: string): Promise<PartnerFunnel> {
  const [clicked, signedUp, convertedRows] = await Promise.all([
    db.referralClick.count({ where: { code } }),
    db.partnerCustomer.count({ where: { partnerId } }),
    db.partnerCommission.groupBy({ by: ["customerId"], where: { partnerId } }),
  ]);
  return { clicked, signedUp, converted: convertedRows.length };
}

