1	"use server";
2	
3	import { requireUser } from "@/lib/auth";
4	import { orderQuote, OrderError, type OrderIntent } from "@/lib/order";
5	import { couponAccountEligibilityError } from "@/lib/coupon-redemption";
6	
7	/* Live pricing for the deploy wizard.
8	 *
9	 * WHY THIS FILE EXISTS AT ALL. The design's wizard shows a running total that
10	 * updates as you pick a plan, a term, add-ons and disk. The design sandbox
11	 * computed that total in the browser from a fixture table. That must not
12	 * survive the port: a price the VIEW derives is a second pricing formula, and
13	 * the moment it disagrees with `orderQuote` the customer is shown one number
14	 * and charged another. So the wizard asks the server what things cost, every
15	 * time, and renders only what comes back.
16	 *
17	 * WHY IT IS ITS OWN FILE. `"use server"` makes EVERY export in a module
18	 * network-callable by anyone who can reach the app. This module therefore
19	 * exports exactly one thing, and that thing:
20	 *   - requires a signed-in user,
21	 *   - only READS (orderQuote never writes, never charges, never reserves),
22	 *   - returns a price, never an order.
23	 * Do not add a second export here, and do not let anything that mutates share
24	 * this file. The same property is why lib/safe-next.ts and lib/totp-verify.ts
25	 * were split out — in this codebase that mistake has already produced one
26	 * public brute-force oracle.
27	 */
28	
29	export type QuotedPrice = {
30	  ok: true;
31	  /** Net, pre-tax, in cents — the figure every other number is derived from. */
32	  chargeCents: number;
33	  /** What is actually taken: `chargeCents + taxCents`. */
34	  taxCents: number;
35	  totalCents: number;
36	  months: number;
37	  /** Regular (undiscounted) plan cash for the term, for an honest "was" price. */
38	  regularPlanCents: number;
39	  /* A promo is only reported when it actually MOVED the price. `orderQuote`
40	     returns the active promo's name regardless of whether it applied to this
41	     product — first-month-free is hosting-only, so a VPS order came back
42	     carrying "First month free" while being charged in full. Showing that is
43	     worse than showing nothing: it tells the customer they are not paying for
44	     something they are paying for. */
45	  promoName: string;
46	  promoPercent: number;
47	  promoCreditCents: number;
48	  couponLabel: string | null;
49	  couponDiscountCents: number;
50	  couponError: string | null;
51	  extraDiskCents: number;
52	  backupCents: number;
53	  /** Intro pricing, so the wizard can say "then $X/mo" rather than implying
54	      forever. Both are null unless the plan ACTUALLY carries an intro rate —
55	      a renewal figure shown without one just restates the price as a warning. */
56	  introMonthlyCents: number | null;
57	  introRenewalMonthly: number | null;
58	  /** What this order actually renews at, every cycle — plan (no coupon/intro
59	   *  discount, both first-term-only) plus every recurring add-on at full
60	   *  price. Always populated, unlike introRenewalMonthly. See lib/order.ts's
61	   *  renewalTotalCents for the full reasoning. */
62	  renewalTotalCents: number;
63	};
64	
65	export type QuoteResult = QuotedPrice | { ok: false; error: string };
66	
67	/**
68	 * Price a wizard selection. Read-only.
69	 *
70	 * Errors are RETURNED, not thrown: an incomplete selection (no plan chosen yet)
71	 * is the normal state of a wizard, not an exception, and the cart should show
72	 * nothing rather than an error boundary.
73	 */
74	export async function quoteOrder(intent: OrderIntent): Promise<QuoteResult> {
75	  const user = await requireUser();
76	  try {
77	    const q = await orderQuote(intent);
78	    const taxCents = 0; // orderQuote returns net; tax is applied on the charge leg.
79	    // Catalog-level checks (service/plan/term/dates/global cap) already ran
80	    // inside orderQuote; this adds the two ACCOUNT-level ones it can't see —
81	    // see couponAccountEligibilityError's own doc comment for why the preview
82	    // needs this too, not just the real reservation at pay time.
83	    let couponDiscountCents = q.couponDiscountCents ?? 0;
84	    let couponLabel: string | null = q.couponLabel ?? null;
85	    let couponError: string | null = q.couponError ?? null;
86	    if (q.couponId && couponDiscountCents > 0) {
87	      const ineligible = await couponAccountEligibilityError({
88	        userId: user.id,
89	        firstTimeOnly: q.couponFirstTimeOnly,
