import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { clientIp } from "@/lib/rate-limit";
import { hashIp } from "@/lib/coupon-order";

/**
 * The REAL Creator Partner link: nxeon.cloud/partner/<code>. This is what a
 * partner is actually given to share — "acts like a coupon code or referral
 * link" (owner's spec) — and, unlike the older `/r/<code>` short link, it
 * RECORDS a real click (ReferralClick — an existing, previously-unused table:
 * see its own schema doc comment, "User.referralCode or ReferralPartner.code")
 * before setting the same `nxeon_ref` cookie and redirecting to /register.
 *
 * `/r/<code>` (app/r/[code]/route.ts) still works — the peer "refer a friend"
 * program uses it too and nothing depended on it changing — but this is the
 * primary route partners are handed, and the one place a partner's real click
 * count comes from (lib/partner-commission.ts partnerFunnel).
 *
 * DELIBERATELY still no gate on whether the code is a real/active partner
 * before recording the click or setting the cookie: a click is a click (even a
 * mistyped or since-paused code is real traffic worth counting), and — exactly
 * like `/r/<code>`'s own doc comment — `register` (lib/actions.ts) is what
 * actually validates the code before anything is attached or charged
 * differently. This route's only job is: record the click, translate the
 * short link into the cookie, redirect.
 */

const REF_COOKIE = "nxeon_ref";
const REF_COOKIE_TTL_SECONDS = 60 * 60 * 24 * 30; // 30 days, matches ReferralCapture / app/r/[code]

export async function GET(req: NextRequest, { params }: { params: Promise<{ code: string }> }) {
  const { code: rawCode } = await params;

  // Redirect against the PUBLIC origin, not req.nextUrl.origin — see app/r/[code]/route.ts's
  // identical comment (behind the nginx proxy the request origin resolves to localhost).
  const publicOrigin = process.env.APP_URL ?? req.nextUrl.origin;
  const res = NextResponse.redirect(new URL("/register", publicOrigin), 302);

  const code = rawCode.trim().toUpperCase().slice(0, 32);
  if (/^[A-Z0-9_-]+$/.test(code)) {
    res.cookies.set(REF_COOKIE, code, {
      path: "/",
      maxAge: REF_COOKIE_TTL_SECONDS,
      sameSite: "lax",
    });
    // Real click tracking — best-effort, never blocks or slows the redirect.
    // ipHash (not the raw IP) matches how every other per-visitor record on this
    // platform stores addresses (coupon/promo redemptions) — enough to dedupe or
    // investigate abuse without holding a raw IP against a marketing click.
    try {
      const ip = clientIp(req.headers);
      const ipHash = ip ? hashIp(ip, process.env.AUTH_SECRET ?? "nxeon") : null;
      await db.referralClick.create({
        data: {
          code,
          ipHash,
          referer: req.headers.get("referer")?.slice(0, 500) || null,
        },
      });
    } catch (e) {
      console.error("[partner-link] click record failed for", code, e);
    }
  }
  return res;
}

