 * AND record one `PartnerPayout` for the partner's real outstanding balance (see
 * PartnerPayout's own doc comment for why the real balance is
 * lifetime-earned-minus-payouts, not a sum of ACCRUED rows — a prior PARTIAL
 * payout via `adminRecordPartnerPayout` already reduced it). This records a
 * settlement OUTSIDE the wallet (partners are typically paid by bank transfer /
 * invoice), so unlike the affiliate cash-out it moves no wallet balance.
 */
export async function adminSettlePartnerCommission(
  partnerId: string
): Promise<{ error?: string; ok?: boolean; count?: number; cents?: number }> {
  const admin = await requireArea("billing");
  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
  if (!partner) return { error: "Partner not found." };

  const { computePartnerSummary } = await import("./partner-commission");
  const summary = await computePartnerSummary(partnerId);
  const cents = summary?.outstandingCents ?? 0;
  const agg = await db.partnerCommission.aggregate({
    where: { partnerId, status: "ACCRUED" },
    _count: true,
  });
  const count = agg._count ?? 0;
  if (cents <= 0) return { error: "Nothing to settle — no outstanding balance." };

