/**
 * Record a PARTIAL (or exact) payment made to a partner off-wallet — "I paid
 * them $340 today even though $412 is accrued" (the owner's own example). Unlike
 * `adminSettlePartnerCommission`, this never touches individual PartnerCommission
 * row statuses — see PartnerPayout's own doc comment for why a separate payments
 * ledger is the honest way to support a partial amount. Refuses to overpay past
 * the real outstanding balance.
 */
export async function adminRecordPartnerPayout(
  partnerId: string,
  amountCents: number,
  note?: string
): Promise<{ error?: string; ok?: boolean }> {
  const admin = await requireArea("billing");
  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
  if (!partner) return { error: "Partner not found." };

  const cents = Math.round(Number(amountCents));
  if (!Number.isFinite(cents) || cents <= 0) return { error: "Enter a positive amount." };

  const { computePartnerSummary } = await import("./partner-commission");
  const summary = await computePartnerSummary(partnerId);
  const outstanding = summary?.outstandingCents ?? 0;
  if (cents > outstanding) {
    return { error: `That's more than the outstanding balance ($${(outstanding / 100).toFixed(2)}).` };
  }

  await db.partnerPayout.create({
    data: { partnerId, amountCents: cents, note: note?.trim().slice(0, 300) || null, createdById: admin.id },
  });
  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: "partner.payout",
      detail: `${partner.code}: $${(cents / 100).toFixed(2)}${note ? ` (${note.trim().slice(0, 100)})` : ""}`,
    },
  });
  revalidatePath(`/admin/partners/${partnerId}`);
  revalidatePath("/admin/partners");
  return { ok: true };
}

