// ---------- Partner login invites (a brand-new account, not a link) ----------

const PARTNER_INVITE_TTL_HOURS = 72;

/**
 * Invite a brand-new (non-customer) login for a partner who doesn't have an
 * Nxeon account yet — the gap `adminCreatePartner`'s `linkEmail` field can't
 * fill (it only links an EXISTING account). Mirrors `inviteMember`'s token/hash/
 * expiry mechanics (lib/actions-teams.ts) with one real difference: the invitee
 * has no account to sign in with yet, so `acceptPartnerInvite` below creates one
 * — it cannot require `requireUser()` first.
 *
 * Deliberately DOES check whether the address already has an account (unlike
 * `inviteMember`'s enumeration-safe design) — this is an admin-only action
 * against an address the admin themself typed, not a customer-facing endpoint
 * an attacker could probe, and the check exists to point the admin at the right
 * tool (`linkEmail`) instead of silently minting an invite that can never be
 * redeemed (acceptPartnerInvite refuses if the address already has an account).
 */
export async function adminCreatePartnerInvite(
  partnerId: string,
  email: string
): Promise<{ error?: string; ok?: boolean; message?: string }> {
  const admin = await requireArea("billing");
  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
  if (!partner) return { error: "Partner not found." };
  if (partner.userId) return { error: "This partner already has a login." };

  const invitedEmail = String(email ?? "").trim().toLowerCase();
  if (!invitedEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(invitedEmail)) {
    return { error: "Enter a valid email address." };
  }
  const existingUser = await db.user.findUnique({ where: { email: invitedEmail }, select: { id: true } });
  if (existingUser) {
    return { error: `An account already exists for ${invitedEmail} — use "Link existing user by email" instead.` };
  }

  const token = randomBytes(32).toString("base64url");
  const tokenHash = createHash("sha256").update(token).digest("hex");
  const expiresAt = new Date(Date.now() + PARTNER_INVITE_TTL_HOURS * 60 * 60 * 1000);

  await db.partnerInvite.create({
    data: { partnerId, email: invitedEmail, tokenHash, invitedById: admin.id, expiresAt },
  });

  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/+$/, "");
  const acceptUrl = `${base}/partner/invite/accept?token=${encodeURIComponent(token)}`;

  const { sendMail, emails } = await import("./mailer");
  const tpl = emails.genericNotification({
    heading: `You're invited to become an Nxeon Partner`,
    message:
      `Nxeon has invited you to set up your Partner login for <b>${partner.name}</b> (code <b>${partner.code}</b>). ` +
      `Set a password to access your real-time click/signup/conversion tracking, your commission balance and payout ` +
      `history, and your partner link — <code>${base}/partner/${partner.code}</code>. ` +
      `This invitation link expires in ${PARTNER_INVITE_TTL_HOURS} hours.`,
    ctaLabel: "Set up your Partner account",
    ctaUrl: acceptUrl,
  });
  const sent = await sendMail({ to: invitedEmail, subject: tpl.subject, html: tpl.html, template: tpl.template });
  if (!sent) {
    return { error: "We couldn't send that invitation email. Check mail settings and try again." };
  }

  await db.auditLog.create({
    data: { userId: admin.id, action: "partner.invite_sent", detail: `${partner.code} -> ${invitedEmail}` },
  });
  revalidatePath(`/admin/partners/${partnerId}`);
  return { ok: true, message: `Invitation emailed to ${invitedEmail}. It expires in ${PARTNER_INVITE_TTL_HOURS} hours.` };
}

/** Cancel an outstanding partner invite so its link stops working. */
export async function adminRevokePartnerInvite(inviteId: string): Promise<{ error?: string; ok?: boolean }> {
  const admin = await requireArea("billing");
  const invite = await db.partnerInvite.findUnique({ where: { id: inviteId } });
  if (!invite) return { error: "Invite not found." };
  await db.partnerInvite.update({ where: { id: inviteId }, data: { revokedAt: new Date() } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "partner.invite_revoked", detail: `${invite.partnerId}: ${invite.email}` },
  });
  revalidatePath(`/admin/partners/${invite.partnerId}`);
  return { ok: true };
}

/**
 * Redeem a partner invite: create the new account (no `requireUser()` — the
 * whole point is this person has no session yet), link it to the partner, sign
 * them in, and mark the invite accepted. Public (no auth required to CALL this
 * action — a signed-in session is what it CREATES), but the token is the only
 * thing that authorises anything, exactly like acceptInvite's team-invite
 * counterpart.
 */
export async function acceptPartnerInvite(
  _prev: unknown,
  formData: FormData
): Promise<{ error?: string; ok?: boolean }> {
  const token = String(formData.get("token") ?? "");
  const name = String(formData.get("name") ?? "").trim();
  const password = String(formData.get("password") ?? "");

  if (!token) return { error: "Missing invitation token." };
  if (!name) return { error: "Enter your name." };
  if (password.length < 8 || !/[a-zA-Z]/.test(password) || !/[0-9]/.test(password)) {
    return { error: "Password must be at least 8 characters and include a letter and a number." };
  }

  const tokenHash = createHash("sha256").update(token).digest("hex");
  const invite = await db.partnerInvite.findUnique({ where: { tokenHash } });
  if (!invite) return { error: "This invitation link is invalid." };
  if (invite.revokedAt) return { error: "This invitation has been cancelled. Ask for a new one." };
  if (invite.acceptedAt) return { error: "This invitation has already been used. Sign in instead." };
  if (invite.expiresAt < new Date()) return { error: "This invitation link has expired. Ask for a new one." };

  const partner = await db.referralPartner.findUnique({ where: { id: invite.partnerId } });
  if (!partner) return { error: "That partner record no longer exists." };
  if (partner.userId) return { error: "This partner already has a login. Sign in instead." };

  const existing = await db.user.findUnique({ where: { email: invite.email }, select: { id: true } });
  if (existing) {
    return { error: "An account with that email already exists. Sign in and contact support to link it." };
  }

  const user = await db.$transaction(async (tx) => {
    const created = await tx.user.create({
      data: {
        email: invite.email,
        name,
        passwordHash: await bcrypt.hash(password, 12),
      },
    });
    // Guarded: if the code raced with `adminCreatePartner`'s own linkEmail path,
    // the unique `userId` on ReferralPartner stops a partner ever being linked
    // to two accounts (the update simply fails to find a still-unlinked row).
    const linked = await tx.referralPartner.updateMany({
      where: { id: invite.partnerId, userId: null },
      data: { userId: created.id },
    });
    if (linked.count !== 1) throw new Error("PARTNER_ALREADY_LINKED");
    await tx.partnerInvite.update({ where: { id: invite.id }, data: { acceptedAt: new Date() } });
    return created;
  }).catch((e) => {
    if (e instanceof Error && e.message === "PARTNER_ALREADY_LINKED") return null;
    throw e;
  });

  if (!user) return { error: "This partner already has a login. Sign in instead." };

  await db.auditLog.create({
    data: { userId: user.id, action: "partner.invite_accepted", detail: partner.code },
  });
  await createSession(user.id);
  return { ok: true };
}

