  const token = String(formData.get("token") ?? "");
  const name = String(formData.get("name") ?? "").trim();
  const password = String(formData.get("password") ?? "");

  if (!token) return { error: "Missing invitation token." };
  if (!name) return { error: "Enter your name." };
  if (password.length < 8 || !/[a-zA-Z]/.test(password) || !/[0-9]/.test(password)) {
    return { error: "Password must be at least 8 characters and include a letter and a number." };
  }

  const tokenHash = createHash("sha256").update(token).digest("hex");
  const invite = await db.partnerInvite.findUnique({ where: { tokenHash } });
  if (!invite) return { error: "This invitation link is invalid." };
  if (invite.revokedAt) return { error: "This invitation has been cancelled. Ask for a new one." };
  if (invite.acceptedAt) return { error: "This invitation has already been used. Sign in instead." };
  if (invite.expiresAt < new Date()) return { error: "This invitation link has expired. Ask for a new one." };

  const partner = await db.referralPartner.findUnique({ where: { id: invite.partnerId } });
  if (!partner) return { error: "That partner record no longer exists." };
  if (partner.userId) return { error: "This partner already has a login. Sign in instead." };

  const existing = await db.user.findUnique({ where: { email: invite.email }, select: { id: true } });
  if (existing) {
    return { error: "An account with that email already exists. Sign in and contact support to link it." };
  }

  const user = await db.$transaction(async (tx) => {
    const created = await tx.user.create({
      data: {
        email: invite.email,
        name,
        passwordHash: await bcrypt.hash(password, 12),
      },
    });
    // Guarded: if the code raced with `adminCreatePartner`'s own linkEmail path,
    // the unique `userId` on ReferralPartner stops a partner ever being linked
    // to two accounts (the update simply fails to find a still-unlinked row).
    const linked = await tx.referralPartner.updateMany({
      where: { id: invite.partnerId, userId: null },
      data: { userId: created.id },
    });
    if (linked.count !== 1) throw new Error("PARTNER_ALREADY_LINKED");
    await tx.partnerInvite.update({ where: { id: invite.id }, data: { acceptedAt: new Date() } });
    return created;
  }).catch((e) => {
    if (e instanceof Error && e.message === "PARTNER_ALREADY_LINKED") return null;
    throw e;
  });

  if (!user) return { error: "This partner already has a login. Sign in instead." };

  await db.auditLog.create({
    data: { userId: user.id, action: "partner.invite_accepted", detail: partner.code },
  });
  await createSession(user.id);
  return { ok: true };
}

