 * the token isn't consumed until the form actually submits to
 * acceptPartnerInvite, so refreshing or merely opening this link never creates
 * an account (same "a mutation must never fire on page load" discipline as the
 * team-invite accept page).
 */
export default async function PartnerInviteAcceptPage({
  searchParams,
}: {
  searchParams: Promise<{ token?: string }>;
}) {
  const { token } = await searchParams;

  // Already signed in as someone? This flow is for a brand-new partner login —
  // send them onward rather than asking them to abandon their current session.
  const existingSession = await currentUser();
  if (existingSession) redirect("/dashboard");

  if (!token) {
    return (
      <AuthShell heading="Invalid invitation" sub="This partner invitation link is missing its token." bullets={[]}>
        <p className="text-sm text-slate-400">Ask whoever sent you this link for a fresh one.</p>
      </AuthShell>
    );
  }

  const tokenHash = createHash("sha256").update(token).digest("hex");
  const invite = await db.partnerInvite.findUnique({
    where: { tokenHash },
    include: { partner: { select: { name: true, code: true, userId: true } } },
  });

  const problem = !invite
    ? "This invitation link is invalid."
    : invite.revokedAt
      ? "This invitation has been cancelled. Ask for a new one."
      : invite.acceptedAt
        ? "This invitation has already been used. Sign in instead."
        : invite.expiresAt < new Date()
          ? "This invitation link has expired. Ask for a new one."
          : invite.partner.userId
            ? "This partner already has a login. Sign in instead."
            : null;

  if (problem || !invite) {
    return (
      <AuthShell heading="Invitation unavailable" sub={problem ?? "Something went wrong."} bullets={[]}>
        <a href="/login" className="text-sm font-semibold text-brand-300 hover:underline">
          Go to sign in
        </a>
      </AuthShell>
    );
  }

  return (
    <AuthShell
      heading={`Join ${invite.partner.name} on Nxeon`}
      sub={`Set up your Partner login for code ${invite.partner.code} — real click/signup/conversion tracking, commission balance and payouts, all in one place.`}
      bullets={[
        "50% off your referred customers' first purchase, 10% off every purchase after — for as long as they stay",
        "A lifetime commission on every qualifying charge they make",
        "Your own real-time click, signup and conversion analytics",
      ]}
    >
      <PartnerInviteAcceptForm token={token} email={invite.email} />
    </AuthShell>
  );
}

