// ---------- Record a partial/specific payout ----------

export function RecordPayoutForm({ partnerId, outstandingCents }: { partnerId: string; outstandingCents: number }) {
  const [amount, setAmount] = useState("");
  const [note, setNote] = useState("");
  const [msg, setMsg] = useState<{ ok?: boolean; error?: string } | null>(null);
  const [pending, start] = useTransition();

  return (
    <div className="space-y-2">
      <p className="text-xs text-slate-500">
        Record a specific amount paid (e.g. paid $340 today off a $412 balance) without settling the rest.
      </p>
      <Msg msg={msg} />
      <div className="flex flex-wrap items-end gap-2">
        <div>
          <label className="label">Amount ($)</label>
          <input
            className="input w-28"
            type="number"
            min="0.01"
            step="0.01"
            max={(outstandingCents / 100).toFixed(2)}
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
          />
        </div>
        <div className="min-w-0 flex-1">
          <label className="label">Note (optional)</label>
          <input className="input w-full" value={note} onChange={(e) => setNote(e.target.value)} placeholder="e.g. Wise transfer" />
        </div>
        <button
          className="btn-secondary"
          disabled={pending || !amount || Number(amount) <= 0}
          onClick={() =>
            start(async () => {
              const res = await adminRecordPartnerPayout(partnerId, Math.round(Number(amount) * 100), note || undefined);
              setMsg(res);
              if (res.ok) {
                setAmount("");
                setNote("");
              }
            })
          }
        >
          {pending ? "Recording…" : "Record payout"}
        </button>
      </div>
    </div>
  );
}

// ---------- Partner login invites ----------

export function CreatePartnerInviteForm({ partnerId }: { partnerId: string }) {
  const [email, setEmail] = useState("");
  const [msg, setMsg] = useState<{ ok?: boolean; error?: string; message?: string } | null>(null);
  const [pending, start] = useTransition();

  return (
    <div className="space-y-2">
      {msg?.error ? (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{msg.error}</div>
      ) : msg?.ok ? (
        <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
          {msg.message ?? "Invitation sent."}
        </div>
      ) : null}
      <div className="flex flex-wrap items-end gap-2">
        <div className="min-w-0 flex-1">
          <label className="label">Invite a new login by email</label>
          <input
            className="input w-full"
            type="email"
            placeholder="partner@example.com"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
        </div>
        <button
          className="btn-primary"
          disabled={pending || !email.trim()}
          onClick={() =>
            start(async () => {
              const res = await adminCreatePartnerInvite(partnerId, email);
              setMsg(res);
              if (res.ok) setEmail("");
            })
          }
        >
          {pending ? "Sending…" : "Send invite"}
        </button>
      </div>
    </div>
  );
}

