      disabled={pending}
      onClick={() => {
        if (!confirm("Cancel this invitation? The link will stop working.")) return;
        start(async () => {
          await adminRevokePartnerInvite(inviteId);
        });
      }}
    >
      {pending ? "Cancelling…" : "Cancel"}
    </button>
  );
}

