import { genDefaultVpsHostname } from "@/lib/hostname-shared";
import { checkHostnameAvailable } from "@/lib/actions-hostname-check";

/* Order state for the deploy wizard.
 *
 * Ported from the design sandbox with ONE structural change, and it is the
 * important one: the sandbox derived every money figure here in the browser
 * (`dueToday`, `saved`, `walletApplied`, `cardDue`) from a fixture price table.
 * None of that survives. The server is asked what the selection costs, and this
 * context only holds the answer. A price the browser works out is a second
 * pricing formula, and the first time it disagrees with `orderQuote` a customer
 * is shown one number and charged another.
 *
 * Kept exactly as designed:
 *  - Choosing a service seeds a COMPLETE, working configuration, so the order is
 *    buyable without touching anything. Only free defaults are pre-set; nothing
 *    that adds to the total is ever ticked for you.
 *  - Once a service is picked nothing is gated — you can commit from anywhere.
 *  - This is deliberately NOT a <form>. On the live platform an unkeyed ternary
 *    once made Continue and Deploy the same DOM node and charged five customers
 *    four steps early. The commit action is its own button and nothing else can
 *    submit.
 */

