1	import { test } from "node:test";
2	import assert from "node:assert/strict";
3	import { readFileSync } from "node:fs";
4	import { renewalCharge, type PricedServer, type RenewalPrices } from "../lib/renewal-charge.ts";
5	
6	/**
7	 * The cancel-plan retention offer ("stay and save 50% off your next renewal",
8	 * lib/actions-server-lifecycle.ts claimRetentionOffer + Server.
9	 * pendingRenewalDiscountPercent). Three guarantees, matching the shape of
10	 * test/money-core-guards.test.ts: arithmetic asserted directly against the
11	 * pure `renewalCharge` formula, and the parts that live inside "use server"
12	 * files (the clearing writes, the one-per-account claim) asserted against the
13	 * file's own CODE, comments stripped first so a fix's own explanatory comment
14	 * can never be mistaken for the guarantee it describes.
15	 *
16	 * (a) the discount actually reduces the very next renewal charge by 50%
17	 * (b) it does NOT apply to the renewal after that
18	 * (c) an account that already redeemed it once cannot get it offered/applied again
19	 */
20	
21	function code(relative: string): string {
22	  return readFileSync(new URL(relative, import.meta.url), "utf8")
23	    .replace(/\/\*[\s\S]*?\*\//g, "")
24	    .replace(/^\s*\/\/.*$/gm, "");
25	}
26	
27	function fn(src: string, declaration: string): string {
28	  const start = src.indexOf(declaration);
29	  assert.notEqual(start, -1, `${declaration} not found`);
30	  const rest = src.slice(start + declaration.length);
31	  const next = rest.search(/\nexport (async )?(function|const|type|class)/);
32	  const body = next === -1 ? rest : rest.slice(0, next);
33	  assert.ok(body.length > 0, `${declaration} produced an empty body`);
34	  return body;
35	}
36	
37	const LIFECYCLE = code("../lib/actions-server-lifecycle.ts");
38	const BILLING = code("../worker/billing.ts");
39	const ACTIONS = code("../lib/actions.ts");
40	
41	/* ------------------------------------------------------------------ *
42	 * (a) The discount actually halves the very next renewal charge
43	 * ------------------------------------------------------------------ */
44	
45	const BASE_PRICES: RenewalPrices = {
46	  ipMonthlyCents: 0,
47	  extraDiskPerGbCents: 0,
48	  backupPlusCents: 0,
49	  annualDiscountPct: 0,
50	};
51	
52	function pricedServer(overrides: Partial<PricedServer> = {}): PricedServer {
53	  return {
54	    termMonths: 1,
55	    extraDiskGB: 0,
56	    plan: { name: "Starter", priceCents: 1000 },
57	    gamePlan: null,
58	    dedicatedIp: null,
59	    wantsDedicatedIp: false,
60	    backupTier: "FREE" as PricedServer["backupTier"],
61	    ...overrides,
62	  };
63	}
64	
65	test("a 50% pending retention discount halves the renewal total, exactly", () => {
66	  const full = renewalCharge(pricedServer(), BASE_PRICES);
67	  const discounted = renewalCharge(pricedServer({ pendingRenewalDiscountPercent: 50 }), BASE_PRICES);
68	
69	  assert.equal(full.totalCents, 1000, "sanity: full price is $10.00");
70	  assert.equal(discounted.totalCents, 500, "50% off $10.00 is $5.00");
71	  assert.equal(discounted.retentionDiscountCents, 500, "the discount line reports exactly what was shaved off");
72	  assert.equal(discounted.netCents + discounted.retentionDiscountCents, full.netCents,
73	    "the pre-discount subtotal must equal the ordinary full-price subtotal, so the invoice's base line + the discount line always reconcile");
74	});
75	
76	test("the discount applies to the WHOLE renewal — plan plus every add-on line — not just the plan", () => {
77	  const withAddons = pricedServer({
78	    extraDiskGB: 20,
79	    dedicatedIp: {},
80	    wantsDedicatedIp: true,
81	  });
82	  const prices: RenewalPrices = { ipMonthlyCents: 200, extraDiskPerGbCents: 10, backupPlusCents: 0, annualDiscountPct: 0 };
83	  const full = renewalCharge(withAddons, prices);
84	  const discounted = renewalCharge({ ...withAddons, pendingRenewalDiscountPercent: 50 }, prices);
85	
86	  // plan 1000 + ip 200 + disk (20 * 10) 200 = 1400 full; half of that is 700.
87	  assert.equal(full.totalCents, 1400);
88	  assert.equal(discounted.totalCents, 700);
89	  assert.equal(discounted.retentionDiscountCents, 700);
90	});
91	
92	test("the discount is applied BEFORE tax, same as every other discount on this platform", () => {
93	  const prices: RenewalPrices = { ...BASE_PRICES, taxRatePercent: 10 };
94	  const discounted = renewalCharge(pricedServer({ pendingRenewalDiscountPercent: 50 }), prices);
95	  // netCents 500 (50% of 1000), tax is 10% of the DISCOUNTED net, not the list price.
96	  assert.equal(discounted.netCents, 500);
97	  assert.equal(discounted.taxCents, 50, "tax must be computed on what the customer actually pays, not the pre-discount list price");
98	  assert.equal(discounted.totalCents, 550);
99	});
100	
101	test("a corrupt/out-of-range stored percent is clamped, never a negative charge or a >100% gift", () => {
102	  const over = renewalCharge(pricedServer({ pendingRenewalDiscountPercent: 150 }), BASE_PRICES);
103	  assert.equal(over.totalCents, 0, "clamped to 100%, not allowed to go negative");
104	
105	  const negative = renewalCharge(pricedServer({ pendingRenewalDiscountPercent: -20 }), BASE_PRICES);
106	  assert.equal(negative.totalCents, 1000, "a negative stored value must never mean a SURCHARGE — treated as no discount");
107	});
108	
109	/* ------------------------------------------------------------------ *
110	 * (b) It does NOT apply to the renewal after that
111	 * ------------------------------------------------------------------ */
112	
113	test("with no pending discount (the post-clear state) the renewal is full price", () => {
114	  const cleared = renewalCharge(pricedServer({ pendingRenewalDiscountPercent: null }), BASE_PRICES);
