import { test } from "node:test";
import assert from "node:assert/strict";
import {
  partnerDiscountTier,
  partnerDiscountPercentForTier,
  partnerDiscountPercent,
  partnerDiscountCentsFor,
  PARTNER_FIRST_PURCHASE_PCT,
  PARTNER_RECURRING_PCT,
} from "../lib/partner-discount.ts";
import { commissionableBaseCents } from "../lib/partner-commission.ts";
import { renewalCharge, type PricedServer, type RenewalPrices } from "../lib/renewal-charge.ts";

/**
 * Creator Partner Program — money-correctness tests, mirroring the shape of
 * test/retention-offer.test.ts and test/coupon-order.test.ts: pure arithmetic
 * asserted directly, no DB, no mocking.
 *
 * Three things under test:
 *  (a) the customer-facing discount tier/percent resolution (50% first
 *      purchase / 10% recurring / 0% not attached or domain), and the pure
 *      cents math that applies it.
 *  (b) the commission dedicated-IP exclusion rule: a partner earns 0% on a
 *      dedicated-IP add-on line, 100% of their normal rate on every other line
 *      in the same order/renewal.
 *  (c) both discounts wired into the ONE renewal formula (renewalCharge),
 *      stacking correctly with the pre-existing one-time retention offer.
 */

/* ------------------------------------------------------------------ *
 * (a) Customer-facing discount tier + percent
 * ------------------------------------------------------------------ */

test("not attached to any partner => NONE, regardless of anything else", () => {
  const tier = partnerDiscountTier({ attached: false, partnerActive: true, isDomain: false, firstPurchaseAvailable: true });
  assert.equal(tier, "NONE");
  assert.equal(partnerDiscountPercentForTier(tier), 0);
});

test("attached to a PAUSED partner => NONE — pausing stops the customer discount too, not just new commission", () => {
  const tier = partnerDiscountTier({ attached: true, partnerActive: false, isDomain: false, firstPurchaseAvailable: true });
  assert.equal(tier, "NONE");
});

test("a domain purchase is NEVER discounted, even on a genuine first purchase with an active partner", () => {
  const tier = partnerDiscountTier({ attached: true, partnerActive: true, isDomain: true, firstPurchaseAvailable: true });
  assert.equal(tier, "NONE");
});

test("attached + active + first purchase still available => FIRST (50%)", () => {
  const tier = partnerDiscountTier({ attached: true, partnerActive: true, isDomain: false, firstPurchaseAvailable: true });
  assert.equal(tier, "FIRST");
  assert.equal(partnerDiscountPercentForTier(tier), PARTNER_FIRST_PURCHASE_PCT);
  assert.equal(PARTNER_FIRST_PURCHASE_PCT, 50, "the owner's verbatim spec: 50% off the first purchase");
});

test("attached + active + first purchase already used => RECURRING (10%), forever", () => {
  const tier = partnerDiscountTier({ attached: true, partnerActive: true, isDomain: false, firstPurchaseAvailable: false });
  assert.equal(tier, "RECURRING");
  assert.equal(partnerDiscountPercentForTier(tier), PARTNER_RECURRING_PCT);
  assert.equal(PARTNER_RECURRING_PCT, 10, "the owner's verbatim spec: 10% off every purchase after the first");
});

test("a renewal must never be priced at the FIRST tier — callers always pass firstPurchaseAvailable:false for a renewal", () => {
  // This is the contract lib/partner-pricing.ts's partnerDiscountForRenewal
  // relies on: renewalCharge itself has no notion of "first purchase" at all,
  // it only ever sees a flat RenewalPrices.partnerDiscountPercent. Asserted
  // here as a property of partnerDiscountTier so the rule can't silently regress.
  const { tier } = partnerDiscountPercent({ attached: true, partnerActive: true, isDomain: false, firstPurchaseAvailable: false });
  assert.notEqual(tier, "FIRST");
});

test("partnerDiscountCentsFor: ordinary percentage math, rounded", () => {
  assert.equal(partnerDiscountCentsFor(1000, 50), 500);
  assert.equal(partnerDiscountCentsFor(999, 10), 100, "rounds to the nearest cent");
  assert.equal(partnerDiscountCentsFor(0, 50), 0);
});

test("partnerDiscountCentsFor clamps a corrupt percent — never negative, never over the full amount", () => {
  assert.equal(partnerDiscountCentsFor(1000, 150), 1000, "clamped to 100%, never a bigger-than-the-charge discount");
  assert.equal(partnerDiscountCentsFor(1000, -20), 0, "a negative percent must never mean a surcharge");
});

/* ------------------------------------------------------------------ *
 * (b) Commission dedicated-IP exclusion — the money-correctness boundary
 *     cases the feature spec calls out by name.
 * ------------------------------------------------------------------ */

test("an order with ONLY a dedicated IP earns the partner $0 commission", () => {
  // netCents 300 (a bare $3 dedicated-IP line, nothing else on the invoice).
  assert.equal(commissionableBaseCents(300, 300), 0);
});

test("a renewal with a dedicated IP alongside other lines excludes ONLY the IP portion", () => {
  // plan $10.00 + IP $3.00 = $13.00 net; commission base must be exactly $10.00.
  assert.equal(commissionableBaseCents(1300, 300), 1000);
});

test("a mixed-addon order (plan + extra disk + backup + dedicated IP) excludes only the IP line", () => {
  // plan 1000 + disk 200 + backup 150 + ip 300 = 1650 net.
  const netCents = 1000 + 200 + 150 + 300;
  assert.equal(commissionableBaseCents(netCents, 300), 1350, "every line except the $3.00 IP line still earns commission");
});

test("an order with NO dedicated IP is completely unaffected", () => {
  assert.equal(commissionableBaseCents(1000, 0), 1000);
});

test("commissionableBaseCents clamps a corrupt/negative dedicatedIpCents rather than inflating the base", () => {
  assert.equal(commissionableBaseCents(1000, -500), 1000, "a negative IP figure must never GROW the commissionable base");
  assert.equal(commissionableBaseCents(500, 900), 0, "an IP figure larger than the net charge floors at 0, never negative");
});

/* ------------------------------------------------------------------ *
 * (c) Both discounts wired into the ONE renewal formula
 * ------------------------------------------------------------------ */

const BASE_PRICES: RenewalPrices = {
  ipMonthlyCents: 0,
  extraDiskPerGbCents: 0,
  backupPlusCents: 0,
  annualDiscountPct: 0,
};

function pricedServer(overrides: Partial<PricedServer> = {}): PricedServer {
  return {
    termMonths: 1,
    extraDiskGB: 0,
    plan: { name: "Starter", priceCents: 1000 },
    gamePlan: null,
    dedicatedIp: null,
    wantsDedicatedIp: false,
    backupTier: "FREE" as PricedServer["backupTier"],
    ...overrides,
  };
}

test("renewalCharge: no partnerDiscountPercent passed => identical to pre-feature behavior (0% off)", () => {
  const charge = renewalCharge(pricedServer(), BASE_PRICES);
  assert.equal(charge.totalCents, 1000);
  assert.equal(charge.partnerDiscountCents, 0);
  assert.equal(charge.partnerDiscountPercent, 0);
});

test("renewalCharge: a partner-attached customer's renewal is 10% off, on the WHOLE renewal including the dedicated IP", () => {
  const server = pricedServer({ extraDiskGB: 10, dedicatedIp: {}, wantsDedicatedIp: true });
  const prices: RenewalPrices = { ipMonthlyCents: 200, extraDiskPerGbCents: 10, backupPlusCents: 0, annualDiscountPct: 0, partnerDiscountPercent: 10 };
  // plan 1000 + ip 200 + disk 100 = 1300 full; 10% off = 130.
  const charge = renewalCharge(server, prices);
  assert.equal(charge.ipCents, 200, "the IP portion is broken out for the commission engine to exclude");
  assert.equal(charge.partnerDiscountPercent, 10);
  assert.equal(charge.partnerDiscountCents, 130);
  assert.equal(charge.totalCents, 1170);
});

test("renewalCharge: the retention offer and the partner discount STACK — retention first, partner discount on what's left", () => {
  const server = pricedServer({ pendingRenewalDiscountPercent: 50 });
  const prices: RenewalPrices = { ...BASE_PRICES, partnerDiscountPercent: 10 };
  const charge = renewalCharge(server, prices);
  // 1000 -> retention 50% off -> 500 -> partner 10% off the remaining 500 -> 450.
  assert.equal(charge.retentionDiscountCents, 500);
  assert.equal(charge.partnerDiscountCents, 50);
  assert.equal(charge.totalCents, 450);
  // The two discount lines plus the final net must reconstruct the original list price.
  assert.equal(charge.netCents + charge.retentionDiscountCents + charge.partnerDiscountCents, 1000);
});

test("renewalCharge: partner discount is applied BEFORE tax, like every other discount on this platform", () => {
  const prices: RenewalPrices = { ...BASE_PRICES, partnerDiscountPercent: 10, taxRatePercent: 10 };
  const charge = renewalCharge(pricedServer(), prices);
  assert.equal(charge.netCents, 900, "10% off $10.00 is $9.00");
  assert.equal(charge.taxCents, 90, "tax computed on the discounted net, not the list price");
  assert.equal(charge.totalCents, 990);
});

test("renewalCharge: a corrupt/out-of-range partnerDiscountPercent is clamped, same discipline as the retention percent", () => {
  const over = renewalCharge(pricedServer(), { ...BASE_PRICES, partnerDiscountPercent: 150 });
  assert.equal(over.totalCents, 0, "clamped to 100%, never a negative charge");
  const negative = renewalCharge(pricedServer(), { ...BASE_PRICES, partnerDiscountPercent: -20 });
  assert.equal(negative.totalCents, 1000, "a negative value must never mean a surcharge");
});

test("renewalCharge: a game server's dedicated IP is also broken out into ipCents for the commission exclusion", () => {
  const gameServer = pricedServer({
    plan: { name: "Base", priceCents: 500 },
    gamePlan: { name: "Valheim — 4GB", priceCents: 900, termMonths: 1 },
    dedicatedIp: {},
    wantsDedicatedIp: true,
  });
  const prices: RenewalPrices = { ipMonthlyCents: 250, extraDiskPerGbCents: 0, backupPlusCents: 0, annualDiscountPct: 0 };
  const charge = renewalCharge(gameServer, prices);
  assert.equal(charge.ipCents, 250);
  assert.equal(charge.totalCents, 1150, "game plan (900) + IP (250), flat all-in");
});

