import { chromium } from "playwright";

const BASE = "http://localhost:4100";
const EMAIL = process.argv[2];
const PASSWORD = "Testpass123";

const browser = await chromium.launch();
const context = await browser.newContext();
const page = await context.newPage();
page.on("pageerror", (err) => console.log("[pageerror]", err.message.split("\n")[0]));

await page.goto(`${BASE}/login`);
await page.fill('input[name="email"]', EMAIL);
await page.fill('input[name="password"]', PASSWORD);
await page.click('button:has-text("Sign in")');
await page.waitForURL(/\/dashboard/, { timeout: 15000 });

await page.goto(`${BASE}/dashboard/deploy?product=vps`);
await page.waitForTimeout(2000);

async function dismissPopups() {
  for (const sel of ['button:has-text("Skip")', 'button[aria-label="Close"]', 'button:has-text("Got it")']) {
    const el = page.locator(sel).first();
    if (await el.isVisible().catch(() => false)) {
      await el.click({ force: true }).catch(() => {});
      await page.waitForTimeout(300);
    }
  }
}
await dismissPopups();

// The VPS service should already be pre-selected (product=vps); click "Next"
// through Configure -> Region -> Payment -> Deploy, dismissing popups each time.
for (let i = 0; i < 4; i++) {
  await dismissPopups();
  const nextBtn = page.locator('button:has-text("Next")').first();
  await nextBtn.waitFor({ state: "visible", timeout: 10000 });
  await nextBtn.click({ force: true });
  await page.waitForTimeout(1200);
}

await dismissPopups();
await page.waitForTimeout(1000);

// On the final step, confirm the partner-discount badge + price one more time.
const badge = await page.locator("text=Partner discount").first().textContent().catch(() => null);
console.log("Final-step partner discount badge:", badge);

const finalBtn = page.locator('button:has-text("Complete deployment")').first();
await finalBtn.waitFor({ state: "visible", timeout: 10000 });
await finalBtn.click({ force: true });
await page.waitForURL(/\/dashboard\/servers\//, { timeout: 20000 });
console.log("ORDER PLACED. Landed on:", page.url());

await browser.close();

