// Direct invocation of the real order-placement code path (same functions the
// wizard's server action calls), bypassing only the browser UI — still the
// real orderQuote/placeOrder/accrueRecentCommissionsForCustomer functions
// against the real (isolated) database. Verifies: the ACTUAL charge amount is
// 50% off, the invoice carries a Partner discount line + dedicatedIpCents, the
// first-purchase slot gets atomically claimed, and a PartnerCommission row is
// created with the correct commission (dedicated IP line excluded).
import { PrismaClient } from "@prisma/client";
import { orderQuote, placeOrder } from "./lib/order.ts";

const db = new PrismaClient();
const email = process.argv[2];
const user = await db.user.findUniqueOrThrow({ where: { email } });
const plan = await db.plan.findFirstOrThrow({ where: { slug: "standard" } });
const os = await db.osTemplate.findFirstOrThrow({ where: { active: true } });

const intent = {
  planId: plan.id,
  osTemplateId: os.id,
  hostname: `e2e-verify-${Date.now()}`,
  termMonths: 1,
  dedicatedIp: true, // exercise the dedicated-IP commission exclusion too
  sshKeyName: "deploy-key",
};

const quote = await orderQuote(intent, { userId: user.id });
console.log("QUOTE:", JSON.stringify({
  chargeCents: quote.chargeCents,
  regularPlanCents: quote.regularPlanCents,
  ipCents: quote.ipCents,
  partnerDiscountCents: quote.partnerDiscountCents,
  partnerDiscountPercent: quote.partnerDiscountPercent,
  partnerDiscountTier: quote.partnerDiscountTier,
}, null, 2));

