import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();

// Simulate an authenticated admin session for requireArea("billing") by
// calling the real action through its own module (it re-derives the admin
// from the session cookie normally; here we just verify the DB-level ledger
// math directly against the real schema/queries, mirroring what the action does).
const partner = await db.referralPartner.findUniqueOrThrow({ where: { code: "TESTPARTNER" } });
const before = await db.partnerCommission.aggregate({ where: { partnerId: partner.id, status: { not: "VOID" } }, _sum: { amountCents: true } });
console.log("lifetime earned (cents):", before._sum.amountCents);

await db.partnerPayout.create({ data: { partnerId: partner.id, amountCents: 200, note: "Test partial payout" } });

const payoutSum = await db.partnerPayout.aggregate({ where: { partnerId: partner.id }, _sum: { amountCents: true } });
const outstanding = (before._sum.amountCents ?? 0) - (payoutSum._sum.amountCents ?? 0);
console.log("payouts recorded (cents):", payoutSum._sum.amountCents);
console.log("real outstanding balance after partial payout (cents):", outstanding, "expected:", 447 - 200);

await db.$disconnect();

