import { computePartnerSummary } from "./lib/partner-commission.ts";
import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();
const partner = await db.referralPartner.findUniqueOrThrow({ where: { code: "TESTPARTNER" } });
const before = await computePartnerSummary(partner.id);
console.log("BEFORE payout:", JSON.stringify(before));
await db.partnerPayout.create({ data: { partnerId: partner.id, amountCents: 200, note: "Test partial payout" } });
const after = await computePartnerSummary(partner.id);
console.log("AFTER $2.00 partial payout:", JSON.stringify(after));
await db.$disconnect();

